{
    QScriptValue numberFun = engine->newFunction(
        [](QScriptContext *ctx, QScriptEngine *eng) -> QScriptValue {
            QSqlError *self = qscriptvalue_cast<QSqlError*>(ctx->thisObject());
            if (!self)
                return ctx->throwError(QScriptContext::TypeError,
                    QString::fromLatin1("QSqlError.number(): this object is not a QSqlError"));
            bool ok = false;
            int number = self->nativeErrorCode().toInt(&ok);
            return QScriptValue(eng, ok ? number : -1);
        }, 0);
    proto.setProperty(QString::fromLatin1("number"), numberFun, QScriptValue::SkipInEnumeration);
    QScriptValue setNumberFun = engine->newFunction(
        [](QScriptContext *ctx, QScriptEngine *eng) -> QScriptValue {
            QSqlError *self = qscriptvalue_cast<QSqlError*>(ctx->thisObject());
            if (!self)
                return ctx->throwError(QScriptContext::TypeError,
                    QString::fromLatin1("QSqlError.setNumber(): this object is not a QSqlError"));
            if (ctx->argumentCount() != 1 || !ctx->argument(0).isNumber())
                return ctx->throwError(QScriptContext::TypeError,
                    QString::fromLatin1("QSqlError.setNumber(): argument 1 must be a number"));
            int number = ctx->argument(0).toInt32();
            *self = QSqlError(self->driverText(), self->databaseText(),
                              self->type(), QString::number(number));
            return eng->undefinedValue();
        }, 1);
    proto.setProperty(QString::fromLatin1("setNumber"), setNumberFun, QScriptValue::SkipInEnumeration);
    QScriptValue setDriverTextFun = engine->newFunction(
        [](QScriptContext *ctx, QScriptEngine *eng) -> QScriptValue {
            QSqlError *self = qscriptvalue_cast<QSqlError*>(ctx->thisObject());
            if (!self)
                return ctx->throwError(QScriptContext::TypeError,
                    QString::fromLatin1("QSqlError.setDriverText(): this object is not a QSqlError"));
            if (ctx->argumentCount() != 1 || !ctx->argument(0).isString())
                return ctx->throwError(QScriptContext::TypeError,
                    QString::fromLatin1("QSqlError.setDriverText(): argument 1 must be a string"));
            *self = QSqlError(ctx->argument(0).toString(), self->databaseText(),
                              self->type(), self->nativeErrorCode());
            return eng->undefinedValue();
        }, 1);
    proto.setProperty(QString::fromLatin1("setDriverText"), setDriverTextFun, QScriptValue::SkipInEnumeration);
    QScriptValue setDatabaseTextFun = engine->newFunction(
        [](QScriptContext *ctx, QScriptEngine *eng) -> QScriptValue {
            QSqlError *self = qscriptvalue_cast<QSqlError*>(ctx->thisObject());
            if (!self)
                return ctx->throwError(QScriptContext::TypeError,
                    QString::fromLatin1("QSqlError.setDatabaseText(): this object is not a QSqlError"));
            if (ctx->argumentCount() != 1 || !ctx->argument(0).isString())
                return ctx->throwError(QScriptContext::TypeError,
                    QString::fromLatin1("QSqlError.setDatabaseText(): argument 1 must be a string"));
            *self = QSqlError(self->driverText(), ctx->argument(0).toString(),
                              self->type(), self->nativeErrorCode());
            return eng->undefinedValue();
        }, 1);
    proto.setProperty(QString::fromLatin1("setDatabaseText"), setDatabaseTextFun, QScriptValue::SkipInEnumeration);
}
